// PATH: src/models/schemas/api.ts

/**
 * API SCHEMAS: the shapes of what the API takes and answers, generated
 *
 * Purpose:
 *   Written by tools/generate/ from the snapshot of the API's schema,
 *   tools/generate/openapi.v1.json. Do not edit this file. Run
 *   `npm run generate` after the snapshot changes.
 *
 * Shapes:
 *   Each component schema of the API is one type here, and so is the query
 *   of each method that takes one. An object is a Readonly type literal,
 *   the form of a JSON value TypeScript lets stand wherever a JsonValue
 *   may.
 *
 * Answers:
 *   A shape an answer reaches is read tolerantly. A member it does not name
 *   is ignored. A closed set inside it is an OpenSet, the values this
 *   release knows or one a later API release added. A member that may be
 *   null may also be missing, since some answers leave null members out.
 */

import type { JsonValue, OpenSet } from "../records/json.ts";

/**
 * A request for a rendered astrocartography map.
 */
export type AcgMapRequest = Readonly<{
  birth: BirthPayload;
  /**
   * At most 120 characters long.
   *
   * @defaultValue `""`
   */
  place?: string;
  lang?: LanguageCode | null;
}>;

/**
 * One aspect between two planets of the public natal answer.
 */
export type AspectRow = Readonly<{
  a: string;
  b: string;
  aspect: string;
  orb: number;
}>;

/**
 * One operation of a batch.
 */
export type BatchItem = Readonly<{
  technique: string;
  body: Readonly<Record<string, JsonValue>>;
}>;

/**
 * A batch item its technique answered.
 */
export type BatchItemAnswer = Readonly<{
  technique: string;
  ok: true;
  result: JsonValue;
}>;

/**
 * A batch item refused or failed. The items after it still run.
 */
export type BatchItemRefusal = Readonly<{
  technique: string;
  ok: false;
  error: Readonly<Record<string, string>>;
}>;

/**
 * A bounded batch of operations, run synchronously.
 */
export type BatchRequest = Readonly<{
  /**
   * At least 1 item. At most 20 items.
   */
  items: readonly BatchItem[];
}>;

/**
 * A batch's answer, one item for each operation, in the operations' order.
 */
export type BatchResponse = Readonly<{
  count: number;
  results: readonly (BatchItemAnswer | BatchItemRefusal)[];
}>;

/**
 * The BirthDate value, as the API's schema defines it.
 */
export type BirthDate = string;

/**
 * The moment and place a chart is cast for, as every technique request carries it.
 */
export type BirthPayload = Readonly<{
  date: BirthDate;
  time?: ClockTime | null;
  lat: Latitude;
  lon: Longitude;
  timezone?: TimeZoneInput | null;
  houses?: HouseSystemName | null;
}>;

/**
 * A request for a bi-wheel of two charts.
 */
export type BiWheelRequest = Readonly<{
  birth: BirthPayload;
  partner: BirthPayload;
}>;

/**
 * One planet's position in the public natal answer.
 */
export type BodyRow = Readonly<{
  name: string;
  sign?: string | null;
  dms?: string | null;
  house?: number | null;
  retrograde: boolean;
}>;

/**
 * The zone a published calendar states its times in.
 */
export type CalendarZone = "UTC";

/**
 * Which bodies an extended chart computes, and which page of the catalog it returns.
 *
 * `include` adds to the selected categories. `exclusive` leaves the
 * default core out, so only the categories and names asked for are
 * computed.
 */
export type ChartOptions = Readonly<{
  /**
   * At most 15 items.
   */
  categories?: readonly string[];
  /**
   * Traverse the full named catalog in pages. true requires the FULL_CATALOG scope, granted from the Pro plan up.
   *
   * @defaultValue `false`
   */
  all_bodies?: boolean;
  /**
   * Zero-based offset for a paginated catalog response.
   *
   * At least 0.
   *
   * @defaultValue `0`
   */
  catalog_offset?: number;
  /**
   * Bodies requested in one catalog page, at most 160.
   *
   * At least 1. At most 160.
   *
   * @defaultValue `160`
   */
  catalog_limit?: number;
  /**
   * At most 100 items.
   */
  include?: readonly string[];
  /**
   * At most 100 items.
   */
  exclude?: readonly string[];
  /**
   * @defaultValue `false`
   */
  exclusive?: boolean;
}>;

/**
 * An extended chart request: a birth and the options that select its bodies.
 *
 * Callers written before `options` existed send the chart options beside
 * `birth`. They are moved under `options` before the request is checked.
 */
export type ChartRequest = Readonly<{
  birth: BirthPayload;
  options?: ChartOptions;
}>;

/**
 * The ClockTime value, as the API's schema defines it.
 */
export type ClockTime = string;

